 private UsernamePasswordAuthenticationToken auth(Long u,Long i,boolean institucional,boolean recuperacion,String... permisos){var a=Arrays.stream(permisos).map(SimpleGrantedAuthority::new).toList();return new UsernamePasswordAuthenticationToken(new UsuarioPrincipal(u,i,Set.of(),institucional,recuperacion,"qa.periodos","",a),"",a);}
 private UsernamePasswordAuthenticationToken completo(){return auth(99000L,99000L,true,false,"EMPLEADO_LEER","EMPLEADO_LABORAL_LEER","CONDICION_SALARIAL_ADMINISTRAR");}
 private void sesion(){SecurityContextHolder.getContext().setAuthentication(completo());}
 private MockHttpSession web(UsernamePasswordAuthenticationToken a){var session=new MockHttpSession();session.setAttribute("SPRING_SECURITY_CONTEXT",new SecurityContextImpl(a));return session;}
 private CalendarioNominaForm cal(String codigo){var f=new CalendarioNominaForm();f.setCodigo(codigo);f.setNombre("Nómina mensual ficticia "+codigo);f.setFrecuencia("MENSUAL");return f;}
 private CalendarioNominaForm editar(ProgramacionNominaService s,Long id){var c=s.calendario(id);var f=cal(c.codigo());f.setNombre(c.nombre());f.setFrecuencia(c.frecuencia());f.setActivo(c.activo());f.setVersion(c.version());return f;}
 private PeriodoNominaForm periodo(ProgramacionNominaService s,Long cal,String codigo,LocalDate desde,LocalDate hasta){var c=s.contexto(cal);var f=new PeriodoNominaForm();f.setCalendarioId(cal);f.setCalendarioTexto(c.calendario());f.setCalendarioVersion(c.version());f.setCodigo(codigo);f.setNombre("Periodo ficticio "+codigo);f.setInicio(desde);f.setFin(hasta);f.setCorte(hasta.minusDays(3));f.setPago(hasta);f.setMotivo("Organización de fechas sin cálculo ni pago");return f;}
 private FiltroProgramacionNomina filtro(Long cal,String estado,LocalDate desde,LocalDate hasta){return new FiltroProgramacionNomina("",estado,"MENSUAL",cal,null,null,null,desde,hasta,0,10);}
