   for(int n=0;n<12;n++)s.guardarCalendario(null,cal("AUX-PER-"+n));assertThat(s.buscar(false,"",true)).hasSize(11);assertThat(s.buscar(false,"NO",true)).isEmpty();assertThat(s.buscar(false,"%",true)).isEmpty();assertThat(s.calendarios(filtro(null,"ACTIVO",null,null))).hasSize(10);assertThat(s.calendarios(filtro(null,"TODOS",null,null).pagina(100,10))).isEmpty();
