   jdbc.update("update institucion set activo=false where id=99000");assertThat(s.periodo(id)).isNotNull();assertThatThrownBy(()->s.guardarCalendario(null,cal("NO-INACTIVA"))).hasMessageContaining("inactiva");jdbc.update("update institucion set activo=true where id=99000");
   for(var a:List.of(auth(99000L,99000L,false,false,"EMPLEADO_LEER","EMPLEADO_LABORAL_LEER","CONDICION_SALARIAL_ADMINISTRAR"),auth(99000L,99000L,true,true,"EMPLEADO_LEER","EMPLEADO_LABORAL_LEER","CONDICION_SALARIAL_ADMINISTRAR"),auth(99002L,99000L,true,false,"EMPLEADO_LEER","EMPLEADO_LABORAL_LEER","CONDICION_SALARIAL_ADMINISTRAR"))){SecurityContextHolder.getContext().setAuthentication(a);assertThatThrownBy(()->s.periodo(id)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}
   SecurityContextHolder.getContext().setAuthentication(auth(99001L,99001L,true,false,"EMPLEADO_LEER","EMPLEADO_LABORAL_LEER","CONDICION_SALARIAL_ADMINISTRAR"));assertThat(s.periodos(filtro(null,"TODOS",null,null))).isEmpty();assertThatThrownBy(()->s.periodo(id)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->s.historial(true,id,0)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);sesion();
